package com.giftmarket.admin.dto.response;import com.giftmarket.order.entity.*;import com.giftmarket.payment.entity.*;import java.time.LocalDateTime;
public record AdminReturnSummaryResponse(Long returnId,ReturnRequestStatus status,ReturnResponsibility responsibility,LocalDateTime requestedAt,Long orderId,String orderNumber,Long userId,String userName,String userEmail,Long sellerOrderId,Long sellerId,String storeName,String representativeProductName,long productTypeCount,long requestedQuantity,Long refundAmount,PaymentCancellationStatus refundStatus,ShipmentStatus collectionStatus){public static AdminReturnSummaryResponse from(ReturnRequest r,String product,long types,long qty,PaymentCancellation pc){var o=r.getOrder();var u=o.getUser();var so=r.getSellerOrder();var s=so.getSeller();return new AdminReturnSummaryResponse(r.getId(),r.getStatus(),r.getResponsibility(),r.getRequestedAt(),o.getId(),o.getOrderNumber(),u.getId(),u.getName(),u.getEmail(),so.getId(),s.getId(),s.getStoreName(),product,types,qty,pc==null?null:pc.getAmount(),pc==null?null:pc.getStatus(),r.getCollectionShipment()==null?null:r.getCollectionShipment().getStatus());}}
